import React, { useCallback, useEffect, useRef, useState } from 'react';
import { scykRoutes } from '../../config/scykRoutes';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { useAppDispatch } from '../../store/hooks';
import { addToast } from '../../store/slices/uiSlice';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import { useFormOptions } from '../../hooks/useFormOptions';
import { useMedicalIncidentPermissions } from '../../hooks/useMedicalIncidentPermissions';
import { medicalIncidentService } from '../../services/medicalIncidents/medicalIncidentService';
import {
  MedicalIncident,
  MedicalIncidentFilters,
  MedicalIncidentStats,
  IncidentStatus,
} from '../../models/MedicalIncident';
import styles from './FallIncidentReportPage.module.css';

import {
  StatsCard,
  StatsCardsGrid,
  TableCard,
  Pagination,
  LinErpListFilterBar,
  LinReportPeriodSelectorFields,
  SearchTextInput,
  Select,
  SelectOption,
} from '@linm-soft-org/linm-web-common-components';
import { currentYearDateRange, useReportPeriodFilter } from '../../hooks/useReportPeriodFilter';
import { ErpFilterCardHeader } from '../../components/layout/ErpFilterCardHeader';

const TEST_ID_PREFIX = 'fall-incident-report';
const PAGE_SIZE = 20;

interface FilterState {
  search?: string;
  reportingDepartmentId?: string;
  dateFrom?: string;
  dateTo?: string;
}

const FallIncidentReportPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const appNavigate = useAppNavigate();
  const { isReporterScope } = useMedicalIncidentPermissions();
  const { departmentOptions } = useFormOptions('incident-list');

  const yearDefault = currentYearDateRange();
  const [filters, setFilters] = useState<FilterState>(yearDefault);
  const [draft, setDraft] = useState<FilterState>(yearDefault);
  const [items, setItems] = useState<MedicalIncident[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const showLoading = useMinLoadingTime(loading);
  const cancelRef = useRef(false);

  // ── Stats: reload when scope filters change (parity incident list · GetStatsAsync) ──
  const [stats, setStats] = useState<MedicalIncidentStats | null>(null);
  const [statsLoading, setStatsLoading] = useState(true);
  const statsCancelRef = useRef(false);

  useEffect(() => {
    statsCancelRef.current = false;
    setStatsLoading(true);
    const t = setTimeout(async () => {
      try {
        const s = await medicalIncidentService.getStats({
          hasFall: true,
          ...(filters.reportingDepartmentId && { reportingDepartmentId: filters.reportingDepartmentId }),
          ...(filters.dateFrom && { dateFrom: filters.dateFrom }),
          ...(filters.dateTo && { dateTo: filters.dateTo }),
        });
        if (!statsCancelRef.current) { setStats(s); setStatsLoading(false); }
      } catch {
        if (!statsCancelRef.current) setStatsLoading(false);
      }
    }, 0);
    return () => { clearTimeout(t); statsCancelRef.current = true; };
  }, [filters.reportingDepartmentId, filters.dateFrom, filters.dateTo]);

  // ── List: reloads when filters/page change ─────────────────────────────────
  const load = useCallback(async (f: FilterState, p: number) => {
    cancelRef.current = false;
    setLoading(true);
    try {
      const apiFilters: MedicalIncidentFilters = {
        hasFall: true,
        isNotMedicalIncident: false,
        ...(f.dateFrom ? { dateFrom: f.dateFrom } : {}),
        ...(f.dateTo ? { dateTo: f.dateTo } : {}),
        ...(f.search ? { search: f.search } : {}),
        ...(f.reportingDepartmentId ? { reportingDepartmentId: f.reportingDepartmentId } : {}),
      };
      const result = await medicalIncidentService.getList(apiFilters, p, PAGE_SIZE);
      if (cancelRef.current) return;
      setItems(result.items);
      setTotal(result.totalCount ?? result.total ?? 0);
    } catch {
      if (!cancelRef.current) dispatch(addToast({ type: 'error', message: 'Không thể tải danh sách sự cố té ngã' }));
    } finally {
      if (!cancelRef.current) setLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    setDraft(filters);
  }, [filters]);

  useEffect(() => {
    const t = setTimeout(() => load(filters, page), 0);
    return () => { clearTimeout(t); cancelRef.current = true; };
  }, [load, filters, page]);

  const commitFilters = (next: FilterState) => {
    const applied: FilterState = {
      ...next,
      search: next.search?.trim() || undefined,
      reportingDepartmentId: next.reportingDepartmentId || undefined,
    };
    setFilters(applied);
    setPage(1);
  };

  const commitPeriodDates = useCallback((dateFrom: string, dateTo: string) => {
    setDraft((prev) => ({ ...prev, dateFrom, dateTo }));
    setFilters((prev) => ({ ...prev, dateFrom, dateTo }));
    setPage(1);
  }, []);

  const period = useReportPeriodFilter(commitPeriodDates, 'year');

  const handleSearch = () =>
    commitFilters({
      ...draft,
      dateFrom: period.fromDate || draft.dateFrom,
      dateTo: period.toDate || draft.dateTo,
    });

  const handleClear = () => {
    period.resetToDefaultYear();
    const next = currentYearDateRange();
    setDraft(next);
    setFilters(next);
    setPage(1);
  };

  const hasActiveFilters = !!(
    draft.search ||
    draft.reportingDepartmentId ||
    period.viewMode !== 'year'
  );

  const deptOptions: SelectOption[] = [
    { value: '', label: 'Tất cả khoa báo cáo' },
    ...departmentOptions,
  ];

  const statusColor: Record<string, string> = {
    [IncidentStatus.Submitted]: '#3b82f6',
    [IncidentStatus.InAnalysis]: '#f59e0b',
    [IncidentStatus.Resolved]: '#10b981',
    [IncidentStatus.Closed]: '#6b7280',
    [IncidentStatus.Draft]: '#94a3b8',
  };

  const statusLabel: Record<string, string> = {
    [IncidentStatus.Draft]: 'Nháp',
    [IncidentStatus.Submitted]: 'Đã gửi',
    [IncidentStatus.InAnalysis]: 'Đang phân tích',
    [IncidentStatus.Resolved]: 'Đã hoàn thành',
    [IncidentStatus.Closed]: 'Đã đóng',
  };

  const showStatsLoading = statsLoading;
  const totalPages = total > 0 ? Math.ceil(total / PAGE_SIZE) : 1;

  return (
    <div className={styles.page} data-report-list-page data-lin-list-layout="erp-filter-bar">
      <div className={styles.header}>
        <h1 className={styles.title}>
          <i className="fas fa-walking" /> Báo Cáo Sự Cố Té Ngã
        </h1>
      </div>

      {isReporterScope && (
        <div className={styles.roleBanner}>
          <i className="fas fa-user-shield" />
          <span>Danh sách <strong>sự cố té ngã do bạn tạo</strong>.</span>
        </div>
      )}

      {/* Stats — scope filters (khoa · ngày); search chỉ lọc bảng */}
      <StatsCardsGrid>
        <StatsCard label="Tổng sự cố té ngã" value={stats?.total ?? 0} icon="fas fa-walking" variant="primary" loading={showStatsLoading} />
        <StatsCard label="Đã gửi" value={stats?.submitted ?? 0} icon="fas fa-paper-plane" variant="gray" loading={showStatsLoading} />
        <StatsCard label="Đang phân tích" value={stats?.inAnalysis ?? 0} icon="fas fa-search" variant="warning" loading={showStatsLoading} />
        <StatsCard label="Đã hoàn thành" value={(stats?.resolved ?? 0) + (stats?.closed ?? 0)} icon="fas fa-check-circle" variant="success" loading={showStatsLoading} />
      </StatsCardsGrid>

      {/* Table */}
      <TableCard
        header={
          <ErpFilterCardHeader title="Danh sách sự cố" testIdPrefix={TEST_ID_PREFIX}>
          <LinErpListFilterBar
            testIdPrefix={TEST_ID_PREFIX}
            fromDate={period.fromDate}
            toDate={period.toDate}
            onDateChange={period.handleDateRangeChange}
            onSearch={handleSearch}
            loading={showLoading}
            leading={(
              <>
                <div data-testid={`${TEST_ID_PREFIX}-field-search`}>
                  <SearchTextInput
                    label="Tìm kiếm"
                    placeholder="Tìm theo tên bệnh nhân, mã sự cố..."
                    value={draft.search ?? ''}
                    onChange={(search) => setDraft((prev) => ({ ...prev, search }))}
                    testId={`${TEST_ID_PREFIX}-search-text`}
                  />
                </div>
                <div data-testid={`${TEST_ID_PREFIX}-field-reportingDepartment`}>
                  <Select
                    label="Khoa báo cáo"
                    options={deptOptions}
                    value={draft.reportingDepartmentId ?? ''}
                    onChange={(e) =>
                      setDraft((prev) => ({
                        ...prev,
                        reportingDepartmentId: e.target.value || undefined,
                      }))
                    }
                    size="small"
                  />
                </div>
                {hasActiveFilters && (
                  <div data-testid={`${TEST_ID_PREFIX}-field-clear`}>
                    <button onClick={handleClear} className={styles.clearBtn} type="button">
                      <i className="fas fa-times" /> Xóa lọc
                    </button>
                  </div>
                )}
              </>
            )}
            dateLeading={(
              <LinReportPeriodSelectorFields
                testIdPrefix={TEST_ID_PREFIX}
                labels={period.periodLabels}
                viewMode={period.viewMode}
                month={period.month}
                year={period.year}
                quarter={period.quarter}
                yearOptions={period.yearOptions}
                onViewModeChange={period.handleViewModeChange}
                onMonthChange={period.setMonth}
                onYearChange={period.setYear}
                onQuarterChange={period.setQuarter}
              />
            )}
          />
          </ErpFilterCardHeader>
        }
        footer={
          <Pagination
            currentPage={page}
            totalPages={totalPages}
            totalCount={total}
            pageSize={PAGE_SIZE}
            onPageChange={setPage}
          />
        }
      >
        {showLoading ? (
          <div className={styles.center}><i className="fas fa-spinner fa-spin" /> Đang tải...</div>
        ) : items.length === 0 ? (
          <div className={styles.center}>
            <i className="fas fa-inbox" style={{ fontSize: '2rem', display: 'block', marginBottom: 8 }} />
            Không có sự cố té ngã nào
          </div>
        ) : (
          <div style={{ overflowX: 'auto' }}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th style={{ width: 48 }}>STT</th>
                  <th>Mã sự cố</th>
                  <th>Tên sự cố</th>
                  <th>Bệnh nhân</th>
                  <th>Khoa báo cáo</th>
                  <th>Loại té ngã</th>
                  <th>Trạng thái</th>
                  <th>Ngày xảy ra</th>
                  <th>Người báo cáo</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item, idx) => (
                  <tr key={item.id}>
                    <td style={{ color: 'var(--color-text-muted, #adb5bd)', textAlign: 'center' }}>
                      {(page - 1) * PAGE_SIZE + idx + 1}
                    </td>
                    <td>
                      <button
                        type="button"
                        className={styles.codeLink}
                        onClick={() => appNavigate(scykRoutes.incidents.detail(item.id))}
                      >
                        {item.idCode}
                      </button>
                    </td>
                    <td style={{ maxWidth: 200 }}>{item.incidentName}</td>
                    <td>{item.patientName || '—'}</td>
                    <td>{item.reportingDepartmentName || '—'}</td>
                    <td>
                      <span style={{ fontSize: '0.8rem', color: '#f59e0b' }}>
                        {item.fallSummary || '—'}
                      </span>
                    </td>
                    <td>
                      <span style={{
                        padding: '2px 8px', borderRadius: 12,
                        background: (statusColor[item.status] ?? '#94a3b8') + '20',
                        color: statusColor[item.status] ?? '#94a3b8',
                        fontSize: '0.75rem', fontWeight: 600,
                      }}>
                        {statusLabel[item.status] ?? item.status}
                      </span>
                    </td>
                    <td>{item.occurredAt ? new Date(item.occurredAt).toLocaleDateString('vi-VN') : '—'}</td>
                    <td>{item.createdByName}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </TableCard>
    </div>
  );
};

export default FallIncidentReportPage;
